from collections import defaultdict, deque

def can_white_win(n, edges, colors):
    graph = defaultdict(list)
    for v, u in edges:
        graph[v].append(u)
        graph[u].append(v)

    # Check if there's a path of three vertices in the same color
    def check_win(color):
        for i in range(1, n + 1):
            if colors[i - 1] == color:
                for neighbor in graph[i]:
                    if colors[neighbor - 1] == color:
                        for next_neighbor in graph[neighbor]:
                            if colors[next_neighbor - 1] == color:
                                return True
        return False

    # Simulate the game
    for i in range(n):
        if colors[i] == 'N':
            if check_win('W'):
                return "White"
            colors[i] = 'W'
            if check_win('B'):
                return "Black"
            colors[i] = 'N'

    return "Draw"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1
    results = []

    for _ in range(T):
        n = int(data[index])
        index += 1
        edges = []
        for _ in range(n - 1):
            v = int(data[index])
            u = int(data[index + 1])
            edges.append((v, u))
            index += 2
        colors = data[index]
        index += 1
        results.append(can_white_win(n, edges, list(colors)))

    print("\n".join(results))

if __name__ == "__main__":
    main()
